DELETE  FROM A1_MFG.TF_CVD_CLN_INFO A
WHERE EXISTS (
SELECT 1 FROM(
SELECT TOOL_ID,PARTITION_ID,RUN_ID,START_TIME,UPDATE_TIME FROM(
SELECT
A.* ,ROW_NUMBER()OVER(PARTITION BY TOOL_ID,PARTITION_ID,RUN_ID,START_TIME ORDER BY UPDATE_TIME)RN
FROM A1_MFG.TF_CVD_CLN_INFO A
WHERE  FAB = #{fab,jdbcType=VARCHAR}
)WHERE RN>1
UNION ALL
SELECT TOOL_ID,PARTITION_ID,RUN_ID,START_TIME,UPDATE_TIME FROM A1_MFG.TF_CVD_CLN_INFO WHERE  FAB = #{fab,jdbcType=VARCHAR} AND START_TIME <  SYSDATE-8
)B  WHERE A.TOOL_ID = B.TOOL_ID AND A.PARTITION_ID = B.PARTITION_ID AND A.RUN_ID = B.RUN_ID AND A.START_TIME = B.START_TIME AND A.UPDATE_TIME = B.UPDATE_TIME
)
